const BY_TYPE: Record<string, string> = {
  "openai-compat": "generic",
  lmstudio: "lmstudio",
  llamacpp: "llama",
  openrouter: "openrouter",
  openai: "openai",
  anthropic: "anthropic",
  "opencode-zen": "opencode",
  "opencode-go": "opencode-go",
};

// Custom entries carry a free-form label: use it to recognize llama.cpp and
// friends even though their `type` is the generic `openai-compat`.
const BY_LABEL: Array<[RegExp, string]> = [
  [/ollama/i, "ollama"],
  [/\bllama\b/i, "llama"],
  [/lm\s*studio/i, "lmstudio"],
  [/openrouter/i, "openrouter"],
  [/anthropic|claude/i, "anthropic"],
  [/opencode-go/i, "opencode-go"],
  [/opencode|zen/i, "opencode"],
  [/openai/i, "openai"],
];

/** Icon key for a provider entry; `generic` means no matching brand. */
export function providerIconKey(type: unknown, label?: unknown): string {
  const key = BY_TYPE[String(type || "").toLowerCase()];
  if (key && key !== "generic") return key;
  const name = String(label || "");
  for (const [pattern, match] of BY_LABEL) {
    if (pattern.test(name)) return match;
  }
  return key || "generic";
}

/** Brand SVG (or a neutral Lucide icon) for a provider type/label. */
export function providerIcon(type: unknown, label?: unknown): SVGElement {
  const key = providerIconKey(type, label);
  const brand = BRANDS[key];
  if (!brand) return icon("server");
  const svg = document.createElementNS(SVG_NS, "svg") as SVGSVGElement;
  svg.setAttribute("viewBox", brand.viewBox);
  svg.setAttribute("fill", "currentColor");
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("focusable", "false");
  svg.setAttribute("class", "svg-icon provider-icon provider-icon-" + key);
  brand.paths.forEach((d, i) => {
    const path = document.createElementNS(SVG_NS, "path");
    path.setAttribute("d", d);
    if (brand.dimFirst && i === 0) path.setAttribute("fill-opacity", "0.4");
    svg.appendChild(path);
  });
  return svg;
}
